/** 
 * java.lang.String getMapDirectory() Asks the user to input a valid map name that will be used to form the map directory in the core of TripleA in the class TerritoryData. we need the exact map name as indicated in the XML game file ie."revised" "classic" "pact_of_steel" of course, without the quotes.
 * @return java.lang.String mapDir  the map name
 */
private static String getMapDirectory(){
  if (java.awt.GraphicsEnvironment.isHeadless()) {
    throw new RuntimeException("Cannot display dialog in a headless environment.");
  }
  String mapDir = JOptionPane.showInputDialog(null, "Enter the map name as indicated in the XML Game file");
  if (mapDir != null) {
    return mapDir;
  } else {
    return null;
  }
}
